// Get the raw CSV text
const csvText = msg.payload;

// Split into lines
const lines = csvText.split('\n').filter(line => line.trim().length > 0);

if (lines.length < 2) {
    node.error('CSV file is empty or has no data rows');
    return null;
}

// First line is headers
const headers = lines[0].split(',').map(h => h.trim());

// Parse all data rows
const csvData = [];
let skippedRows = 0;

for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(',');

    if (values.length !== headers.length) {
        // Skip malformed rows
        skippedRows++;
        continue;
    }

    // Create object for this row
    const row = {};
    let hasValidData = false;

    for (let j = 0; j < headers.length; j++) {
        const value = values[j].trim();
        row[headers[j]] = value;

        // Check if this row has any non-empty data
        if (value.length > 0 && value !== '0' && !isNaN(parseFloat(value))) {
            hasValidData = true;
        }
    }

    // Only add rows that have valid data
    // Skip rows where moisture, temperature, and humidity are all empty or zero
    const moisture = parseFloat(row.moisture || 0);
    const temperature = parseFloat(row.temperature || 0);
    const humidity = parseFloat(row.humidity || 0);

    if (moisture !== 0 || temperature !== 0 || humidity !== 0) {
        csvData.push(row);
    } else {
        skippedRows++;
    }
}

// Store in flow context
flow.set('csvData', csvData);
flow.set('tomatoIndex', 0);
flow.set('wheatIndex', 0);

node.status({fill:"green", shape:"dot", text:`Loaded ${csvData.length} rows (skipped ${skippedRows})`});

// Output summary
msg.payload = {
    totalRows: csvData.length,
    skippedRows: skippedRows,
    columns: headers,
    sampleRow: csvData[0]
};

return msg;

// Get CSV data
const csvData = flow.get('csvData') || [];

if (csvData.length === 0) {
    node.error('CSV data not loaded!');
    return null;
}

// Get current index
let index = flow.get('tomatoIndex') || 0;

// Get the row
const row = csvData[index];

// Increment index for next time
index = (index + 1) % csvData.length;
flow.set('tomatoIndex', index);

// Pass the entire row
msg.payload = row;
msg.cropName = 'tomato';

node.status({fill:"blue", shape:"dot", text:`Row ${index}/${csvData.length}`});

return msg;

// Get the raw CSV row
const row = msg.payload;

// Get threshold
const threshold = flow.get('threshold_tomato') || 30;

// Parse values from CSV (they're strings)
const moisture = parseFloat(row.moisture || 0);
const rainfall = parseFloat(row.rainfall || 0);
const temperature = parseFloat(row.temperature || 0);
const humidity = parseFloat(row.humidity || 0);
const pH = parseFloat(row.pH || 0);
const ec = parseFloat(row.EC_dS_m || 0);
const nitrogen = parseFloat(row.Nitrogen_mg_kg || 0);
const phosphorus = parseFloat(row.Phosphorus_mg_kg || 0);
const potassium = parseFloat(row.Potassium_mg_kg || 0);
const light = parseFloat(row.Light_Intensity_lux || 0);
const timestamp = Date.parse(row.timestamp || 0);

// Create sensor data object
const sensorData = {
    moisture: moisture,
    soilTemperature: temperature,
    rainfall: rainfall,
    humidity: humidity,
    lightIntensity: light,
    pH: pH,
    nitrogen: nitrogen,
    phosphorus: phosphorus,
    potassium: potassium,
    ec: ec,
    //timestamp: new Date().toISOString(),
    timestamp: timestamp,
    threshold: threshold,
    status: moisture < threshold ? "ON" : "OFF"
};

msg.payload = sensorData;
msg.topic = "crop/tomato/data";

return msg;

